@Component("onboardingTask-handler")
@ProcessingGroup("onboardingTask-processing-group")
public class OnboardingTaskEventHandler {
	
	// core constructor
	OnboardingTaskEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateOnboardingTaskEvent
     */
    @EventHandler
    public void handle( CreateOnboardingTaskEvent event) {
        entityManager.persist(new OnboardingTask(event.getOnboardingTaskId(), event.getTaskNumber(), event.getName(), event.getDueDate(), event.getEmployee(), event.getAssignedTo(), event.getDependencies(), event.getRelatedOffer(), event.getStatus()));
    }

    /*
     * @param	event UpdateOnboardingTaskEvent
     */
    @EventHandler
    public OnboardingTask handle( UpdateOnboardingTaskEvent event) {
    	entityManager.merge(new OnboardingTask(event.getOnboardingTaskId(), event.getTaskNumber(), event.getName(), event.getDueDate(), event.getEmployee(), event.getAssignedTo(), event.getDependencies(), event.getRelatedOffer(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteOnboardingTaskEvent
     */
    @EventHandler
    public void on( DeleteOnboardingTaskEvent event) {
    	OnboardingTask entity = new OnboardingTask();
   
    	// ------------------------------------------
    	// apply the OnboardingTaskId
    	// ------------------------------------------
    	entity.setOnboardingTaskId( event.getOnboardingTaskId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final OnboardingTaskRepository onboardingTaskEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(OnboardingTaskEventHandler.class.getName());

}
